699	    submitIntervention({ kind: "correction", targetRole: interveneRole });
700	  });
701	  // Passing is a decision, so it goes on the record like any other. Doing
702	  // nothing and choosing to do nothing read identically in a trace otherwise.
703	  els.pass?.addEventListener("click", () => {
704	    if (!game) return;
705	    const withPass = game as PlayableGame & { passRound?: () => { accepted: boolean; error?: { message: string } } };
706	    if (!withPass.passRound) return;
