862	/** The service report: what the shift scored, and what to fix next run. */
863	function getArenaDebriefHtml(): string {
864	  if (!game || game.name !== "restaurant-arena") return "";
865	  const view = arenaView(game) as unknown as { debrief?: ArenaDebrief };
866	  const debrief = view.debrief;
867	  if (!debrief) return "";
868	  // Whatever the target checks already reported is dropped here: showing
869	  // "Takings $96" twice, once as a verdict and once as a stat, made the card
870	  // longer without making it say more.
871	  const checked = new Set((debrief.targets ?? []).map((target) => target.label.toLowerCase()));
872	  const lines = debrief.lines
873	    .filter((line) => !checked.has(line.label.toLowerCase()))
874	    .map(
875	      (line) =>
876	        `<span class="debrief-stat${line.good ? " is-good" : ""}"><small>${escapeHtml(line.label)}</small><strong>${escapeHtml(line.value)}</strong></span>`,
877	    )
878	    .join("");
879	  const lessons = debrief.lessons.map((lesson) => `<li>${escapeHtml(lesson)}</li>`).join("");
880	  // The verdict names which condition decided it. `lines` below are a
881	  // read-at-a-glance summary of the shift on their own thresholds, which are
882	  // not tonight's pass bar — keeping the two apart is what stops a green
883	  // "Walkouts 2" from sitting under a MISSED verdict it actually caused.
884	  const targets = (debrief.targets ?? [])
885	    .map(
886	      (target) =>
887	        `<li class="debrief-check${target.met ? " is-met" : ""}">` +
888	        `<span class="check-mark">${target.met ? "met" : "miss"}</span>` +
889	        `<span class="check-label">${escapeHtml(target.label)}</span>` +
890	        `<span class="check-value">${escapeHtml(target.value)}</span>` +
891	        `<span class="check-req">needs ${escapeHtml(target.requirement)}</span>` +
892	        `</li>`,
893	    )
894	    .join("");
895	  return `
896	    <div class="arena-debrief"${debrief.met ? ' data-met="yes"' : ""}>
897	      <p class="debrief-scope">Local gameplay summary · not an official evaluation</p>
898	      <p class="debrief-target">${debrief.met ? "LOCAL TARGET MET" : "LOCAL TARGET MISSED"}</p>
899	      <p class="debrief-grade"><strong>${escapeHtml(debrief.grade)}</strong> ${escapeHtml(debrief.headline)}</p>
900	      ${targets ? `<p class="debrief-criteria">Local target checks</p><ul class="debrief-checks">${targets}</ul>` : ""}
901	      <p class="debrief-criteria">Raw operational facts</p>
902	      <div class="debrief-stats">${lines}</div>
903	      <p class="debrief-caveat">No wait figure: the engine derives only a whole-shift clock reading, not an arrival-to-seat measurement.</p>
904	      <ul class="debrief-lessons">${lessons}</ul>
905	    </div>`;
906	}
