1	import { buildFullRolePrompt, type PromptBuilderOptions } from "./prompts.js";
2	import { RestaurantGame, type EnvelopeTelemetry } from "./restaurant-game.js";
3	import { ACTION_VERSION, type ActionEnvelope, type Role, type Tool } from "./types.js";
4	import type { TraceV3Model } from "./trace.js";
5	import type { ActionContext, ModelCallMetrics } from "./worker-client.js";
6	
7	/** The small surface the orchestrator needs from WorkerModelClient. */
8	export interface WorkerActionClient {
9	  act(context: ActionContext, systemPrompt: string, turnPrompt: string): Promise<ActionEnvelope>;
10	  /** Metrics from the most recently completed act() call, when the transport reported any. */
11	  lastMetrics?(): ModelCallMetrics | undefined;
12	  abort?(): void;
13	}
14	
15	export const TURN_ORDER: readonly Role[] = ["host", "supply_lead", "chef", "server"];
16	
17	export type WorkerTurnStatus = "accepted" | "rejected" | "fallback" | "paused";
18	
19	export interface WorkerTurn {
20	  role: Role;
21	  status: WorkerTurnStatus;
22	  action?: ActionEnvelope;
23	  error?: string;
24	}
25	
26	export interface OrchestratorTick {
27	  advanced: boolean;
28	  paused: boolean;
29	  complete: boolean;
30	  turns: WorkerTurn[];
31	}
32	
33	export interface WorkerOrchestratorOptions {
34	  /** The model client used for every staff role. */
35	  client: WorkerActionClient;
36	  /** Run roles in this order. Sequential execution keeps every envelope on one tick. */
37	  roles?: readonly Role[];
38	  promptOptions?: PromptBuilderOptions;
39	  /** Wall-clock pacing for start(); a direct runTick() is always immediate. */
40	  tickIntervalMs?: number | (() => number);
41	  now?: () => Date;
42	  requestId?: () => string;
43	  /** Receives individual model/action failures without making the loop stop. */
44	  onError?: (turn: WorkerTurn) => void;
45	  /**
46	   * The model behind every worker turn, recorded on the trace event. Absent
47	   * for environment-driven runs, which have no model to attribute.
48	   */
49	  model?: TraceV3Model;
50	  /** Monotonic clock for latency. Injectable so tests get deterministic numbers. */
51	  elapsedMs?: () => number;
52	  /** Receives each paced round after its state changes are committed. */
53	  onTick?: (report: OrchestratorTick) => void;
54	}
55	
56	const FALLBACKS: Record<Role | "expediter", { tool: Tool; arguments: Record<string, unknown> }> = {
57	  chef: { tool: "inspect", arguments: { targetId: "oven-1" } },
58	  server: { tool: "inspect", arguments: { targetId: "pass" } },
59	  host: { tool: "update_guest", arguments: { message: "Thank you for your patience; we will seat you as soon as a table is ready." } },
60	  supply_lead: { tool: "inspect", arguments: { targetId: "pass" } },
61	  get expediter() {
62	    return this.supply_lead;
63	  },
64	};
65	
66	/**
67	 * Turns the four Restaurant Arena workers into a paced, autonomous shift.
68	 * It deliberately schedules one role at a time: every observation and action
69	 * remains on the current simulator tick, so an earlier worker cannot make a
70	 * later worker submit a stale envelope.
71	 */
72	export class WorkerOrchestrator {
73	  private readonly roles: readonly Role[];
74	  private readonly tickIntervalMs: number | (() => number);
75	  private timer?: ReturnType<typeof setTimeout>;
76	  private running = false;
77	  private paused = false;
78	  private inFlight = false;
79	  private requestSequence = 0;
80	  private requestEpoch = 0;
81	  private roundTick?: number;
82	  private nextRoleIndex = 0;
83	  private readonly roundTurns: WorkerTurn[] = [];
84	  /** When the current decision round's first worker began, for roundMs. */
85	  private roundStartedAt?: number;
86	
87	  constructor(
88	    private readonly game: RestaurantGame,
89	    private readonly options: WorkerOrchestratorOptions,
90	  ) {
91	    this.roles = options.roles ?? TURN_ORDER;
92	    this.game.setExternalControllers(this.roles);
93	    this.tickIntervalMs = options.tickIntervalMs ?? 1_000;
94	  }
95	
96	  isRunning(): boolean {
97	    return this.running;
98	  }
99	
100	  isPaused(): boolean {
101	    return this.paused;
102	  }
103	
104	  /** Pause before a player intervention; no later worker or tick is started. */
105	  pause(): void {
106	    this.paused = true;
107	    this.requestEpoch += 1;
108	    this.options.client.abort?.();
109	    if (this.timer) clearTimeout(this.timer);
110	    this.timer = undefined;
111	  }
