206	function submitTrace(
207	  trace: StoredOverlayTrace,
208	  reason: EpisodeEndReason,
209	  completedScore?: number,
210	): void {
211	  if (!settings.recordingWhilePlaying) return;
212	  try {
213	    trace.endReason ??= reason;
214	    trace.endedAtMs ??= Date.now();
215	    trace.completedScore ??= completedScore;
216	    persistTrace(trace);
217	    const chunks = buildOverlayTraceChunks(
218	      trace,
219	      trace.endReason,
220	      appVersion(),
221	      trace.endedAtMs,
222	    );
223	    void invoke("queue_recording_chunks", {
224	      chunks,
225	      result: buildOverlayGameResult(trace),
226	    }).then(() => {
227	      localStorage.removeItem(`${TRACE_KEY_PREFIX}${trace.gameId}`);
228	    }).catch(() => {
229	      // Keep the compact seed/action journal for the next launch.
230	    });
231	  } catch {
232	    // Keep the journal if replay or serialization fails.
233	  }
234	}
