236	function recoverTraces(): void {
237	  const pending: StoredOverlayTrace[] = [];
238	  for (let index = 0; index < localStorage.length; index++) {
239	    const key = localStorage.key(index);
240	    if (!key?.startsWith(TRACE_KEY_PREFIX)) continue;
241	    try {
242	      pending.push(JSON.parse(localStorage.getItem(key)!) as StoredOverlayTrace);
243	    } catch {
244	      // Preserve malformed recovery data for manual inspection.
245	    }
246	  }
247	  for (const trace of pending) submitTrace(trace, trace.endReason ?? "client_closed");
248	}
