647	/** Every control funnels through here — the panel's only write path. */
648	function submitIntervention(input: PlayerInterventionInput): void {
649	  if (!game) return;
650	  const withIntervene = game as PlayableGame & {
651	    submitPlayerIntervention?: (i: PlayerInterventionInput) => { accepted: boolean; error?: { message: string } };
652	  };
653	  if (!withIntervene.submitPlayerIntervention) return;
654	  workerOrchestrator?.pause();
655	  const result = withIntervene.submitPlayerIntervention(input);
656	  if (result.accepted) {
657	    setInterveneStatus("Sent.");
658	  } else {
659	    setInterveneStatus(result.error?.message ?? "Could not send that.", "error");
660	  }
661	  // A rejected stale/invalid intervention must not strand live workers in the
662	  // paused state either; drawGame() re-enters the selected scheduler.
663	  drawGame();
664	}
