982	/** Export the raw restaurant-arena-trace-v3 JSON or JSONL file. */
983	function exportCurrentTrace(format: "json" | "jsonl" = "json"): void {
984	  if (!game || game.name !== "restaurant-arena") return;
985	  try {
986	    // A shift played in the overlay is live gameplay by definition; synthetic
987	    // and benchmark traces are produced by scripts/export-arena-trace.ts.
988	    const trace = captureArenaTrace(game as unknown as RestaurantGame, {
989	      runKind: "live",
990	      ...(sessionReceiptId ? { sessionId: sessionReceiptId } : {}),
991	    });
992	    const content = format === "jsonl" ? exportTraceJsonl(trace) : exportTraceJson(trace);
993	    // Named by session, not episode: `episodeId` is the scenario, so every
994	    // run of the same seed used to download over the last one (#281).
995	    const filename = `restaurant-arena-trace-${trace.sessionId ?? trace.episodeId}.${format === "jsonl" ? "jsonl" : "json"}`;
996	    const mimeType = format === "jsonl" ? "application/x-ndjson" : "application/json";
997	    const blob = new Blob([content], { type: mimeType });
998	    const url = URL.createObjectURL(blob);
999	    const a = document.createElement("a");
1000	    a.href = url;
1001	    a.download = filename;
1002	    document.body.appendChild(a);
1003	    a.click();
1004	    a.remove();
1005	    URL.revokeObjectURL(url);
1006	
1007	    const btn = screenElement.querySelector<HTMLButtonElement>('[data-action="export-trace"]');
1008	    if (btn) {
1009	      const orig = btn.innerHTML;
1010	      btn.innerHTML = "Exported!";
1011	      setTimeout(() => {
1012	        if (btn) btn.innerHTML = orig;
1013	      }, 2000);
1014	    }
1015	  } catch (err) {
1016	    console.error("Failed to export trace:", err);
1017	  }
1018	}
