/**
 * The only frame sizes the overlay ever asks for, in logical pixels. The
 * browser preview frames itself at the same numbers, so a layout checked in
 * the preview is the layout the native window gets (README → Window sizes).
 */
export const COMPACT_SIZE = { width: 600, height: 850 } as const;
export const EXPANDED_SIZE = { width: 830, height: 900 } as const;
export const PILL_SIZE = { width: 144, height: 48 } as const;
/**
 * The floor's own minimum. It has to come off before the pill is applied --
 * 144 × 48 is smaller than this -- and go back on when the floor returns.
 */
export const MIN_SIZE = { width: 500, height: 700 } as const;

