/**
 * Overwrite the one save slot with the run currently on screen.
 *
 * Called after every recorded action, so the record on disk is never more than
 * one step behind the board: a crash, a shutdown or a closed lid still leaves
 * a run that can be rebuilt. A journal longer than `MAX_ACTIONS` would be
 * rejected by `loadSavedGame`, so it is dropped outright rather than written
 * as a record that silently fails to load.
 */
export function saveGame(saved: Omit<SavedGame, "schemaVersion">, storage: Storage = localStorage): void {
  try {
    if (saved.actions.length > MAX_ACTIONS) {
      storage.removeItem(STORAGE_KEY);
      return;
    }
    storage.setItem(STORAGE_KEY, JSON.stringify({ schemaVersion: 1, ...saved } satisfies SavedGame));
  } catch {
    // A full or unavailable store must never interrupt the run it describes.
  }
}

/** Drop the save slot: the run it described is over or was thrown away. */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Nothing to resume from is the same outcome as failing to clear.
  }
}

/** Rebuild only actions that remain accepted by this version of the game. */

