/**
 * Pause bookkeeping for the overlay session, kept out of `app.ts` because the
 * interesting part is not the DOM: it is remembering *what the clock was
 * doing* before something interrupted it, so resuming puts the shift back
 * where it was instead of starting a service that never opened.
 *
 * Two things pause a shift, and they are not the same event:
 *
 * - the **agent** stopping (the `Stop` hook → `gamepigeon:pause`), which is a
 *   request for the player's attention and raises the pause dialog;
 * - the **player** minimizing to the pill, which must stop the clock too --
 *   a shift left ticking behind a 144 × 48 pill burns down unattended -- but
 *   has nothing to say, so it raises no dialog.
 *
 * Either way the hold is single: a second pause never re-toggles the engine
 * clock (`sim_toggle` is a toggle, so a doubled stop would *start* service
 * again), and the first hold's `resumeClock` reading is the one that survives.
 */

/** What the engine's clock is doing, read off the live view. */
export interface SimSnapshot {
  started: boolean;
  running: boolean;
  /**
   * A decision card already stops the clock on its own (`tickMs()` returns 0
   * while one is open, and the engine refuses `sim_toggle`), so a hold taken
   * during a decision must not claim to have stopped anything.
   */
  decisionOpen?: boolean;
}

export type PauseSource = "agent" | "player";

export interface PauseHold {
  source: PauseSource;
  /** The clock was ticking when the hold was taken, so resuming restarts it. */
  resumeClock: boolean;
  /** The pause dialog is up and owns the keyboard. */
  prompt: boolean;
}

export interface PauseRequest {
  source: PauseSource;
  /**
   * The `autoPauseOnStop` setting. It only governs the agent: a player who
   * turned auto-pause off still expects minimizing to hold their shift.
   */
  autoPause: boolean;
  /** A run is on screen (not the menu, the scores or the gate). */
  inGame: boolean;
  /** That run is already finished, so the end-of-shift card owns the screen. */
  over: boolean;
  sim?: SimSnapshot | undefined;
  hold: PauseHold | null;
}

export interface PausePlan {
  hold: PauseHold | null;
  /** Send the engine's own pause action once, and only once per hold. */
  stopClock: boolean;
}

export interface ResumePlan {
  hold: null;
  /** Restart the clock only if this hold is the reason it stopped. */
  startClock: boolean;
}

/** True only when a `sim_toggle` would actually stop something. */
export function clockRunning(sim: SimSnapshot | undefined): boolean {
  return Boolean(sim?.started && sim.running && !sim.decisionOpen);
}

export function planPause(request: PauseRequest): PausePlan {
  // An agent pause the player switched off changes nothing at all: no dialog,
  // and above all no clock toggle.
  if (request.source === "agent" && !request.autoPause) return { hold: request.hold, stopClock: false };
  // Nothing to hold outside a live run. The window is already on screen by the
  // time this runs, which is all an agent pause needs from the menu.
  if (!request.inGame || request.over) return { hold: null, stopClock: false };

  const prompt = request.source === "agent" || (request.hold?.prompt ?? false);
  if (request.hold) return { hold: { ...request.hold, prompt }, stopClock: false };
  return {
    hold: { source: request.source, resumeClock: clockRunning(request.sim), prompt },
    stopClock: clockRunning(request.sim),
  };
}

export function planResume(hold: PauseHold | null): ResumePlan {
  return { hold: null, startClock: hold?.resumeClock ?? false };
}

