// ── Window chrome ────────────────────────────────────────────────────
//
// Four controls live outside `#screen`, so they are bound once here rather
// than through the screen's click delegation: expand/compact, minimize to the
// pill, shut down for the session, and the pill itself. Every frame the
// overlay ever asks for is one of the four sizes `tauri-bridge` exports.

const chrome = {
  resize: document.querySelector<HTMLButtonElement>("#resize"),
  hide: document.querySelector<HTMLButtonElement>("#hide"),
  shutdown: document.querySelector<HTMLButtonElement>("#shutdown"),
  pill: document.querySelector<HTMLButtonElement>("#pill"),
  pausePrompt: document.querySelector<HTMLElement>("#return-prompt"),
  howToPlay: document.querySelector<HTMLElement>("#how-to-play"),
  signOutPrompt: document.querySelector<HTMLElement>("#signout-prompt"),
};

function floorSize(): { width: number; height: number } {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

async function applyWindowSize(): Promise<void> {
  const size = mode === "pill" ? PILL_SIZE : floorSize();
  const min = mode === "pill" ? PILL_SIZE : MIN_SIZE;
  try {
    // The floor's minimum is larger than the pill, so it has to come off
    // before the pill size can be applied — and go back on with the floor.
    await windowHandle.setMinSize(overlayLogicalSize(min.width, min.height));
    await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
  } catch {
    // A frame that refuses to resize is not a reason to lose the session.
  }
}

/** ↗ while compact, ↙ while expanded — the control names its own next state. */
function renderResizeControl(): void {
  const button = chrome.resize;
  if (!button) return;
  setText(button, expanded ? "↙" : "↗");
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

function toggleWindowSize(): void {
  expanded = !expanded;
  renderResizeControl();
  void applyWindowSize();
}

/**
 * Collapse to the pill. The window stays alive, so the shift survives — but
 * it must not keep ticking behind a 144 × 48 pill nobody is watching, so this
 * takes a player hold on the clock.
 */
function minimizeToPill(): void {
  if (mode === "pill") return;
  holdRun("player");
  mode = "pill";
  document.body.dataset.mode = "pill";
  void applyWindowSize();
  chrome.pill?.focus();
}

function restoreFloor(): void {
  if (mode !== "pill") return;
  mode = "floor";
  delete document.body.dataset.mode;
  // README: the pill restores to the compact floor, whatever it collapsed from.
  expanded = false;
  renderResizeControl();
  // The pill can be dragged anywhere, and a full frame pinned to the corner it
  // was dropped in would open mostly off-screen.
  void applyWindowSize().then(() => windowHandle.center()).catch(() => undefined);
  // An agent pause that landed while the pill was down keeps its dialog (the
  // pill hides dialogs in CSS, it does not answer them); a hold the pill took
  // on its own is released by reopening.
  if (pauseHold && !pauseHold.prompt) resumeRun();
  else refreshPausePrompt();
}

// ── Dialogs ──────────────────────────────────────────────────────────

function dialogOpen(dialog: HTMLElement | null): boolean {
  return Boolean(dialog && !dialog.hidden);
}

/** The pause dialog is a view of the hold, never state of its own. */
function refreshPausePrompt(): void {
  const prompt = chrome.pausePrompt;
  if (!prompt) return;
  const show = pauseHold?.prompt ?? false;
  prompt.hidden = !show;
  if (show && mode !== "pill") document.querySelector<HTMLButtonElement>("#return-code")?.focus();
}

/**
 * The guide is reachable from the menu, the level list, the pause dialog and
 * the arena's own `?` hotspot. Opening it from the pause dialog stacks: the
 * shift is still held, so closing the guide puts the pause dialog back.
 */
function openHowToPlay(): void {
  if (chrome.pausePrompt) chrome.pausePrompt.hidden = true;
  if (!chrome.howToPlay) return;
  chrome.howToPlay.hidden = false;
  document.querySelector<HTMLButtonElement>("#how-to-play-close")?.focus();
}

function closeHowToPlay(): void {
  if (chrome.howToPlay) chrome.howToPlay.hidden = true;
  refreshPausePrompt();
}

function openSignOutPrompt(): void {
  if (!chrome.signOutPrompt) return;
  chrome.signOutPrompt.hidden = false;
  document.querySelector<HTMLButtonElement>("#signout-confirm")?.focus();
}

function closeSignOutPrompt(): void {
  if (chrome.signOutPrompt) chrome.signOutPrompt.hidden = true;
}

/**
 * Signing out ends the shift on the way to the gate: an abandoned run, never
 * a score. The save is left alone — it is stamped with the owner it belongs
 * to, so it stays invisible until that account signs back in.
 */
async function confirmSignOut(): Promise<void> {
  const button = document.querySelector<HTMLButtonElement>("#signout-confirm");
  if (button) button.disabled = true;
  try {
    releaseRun("user_quit");
    await signOut();
    closeSignOutPrompt();
    savedGame = undefined;
    cursor = -1;
    drawGate();
  } catch (err) {
    console.error("Failed to sign out:", err);
    setSyncError("Could not sign out. Try again.");
  } finally {
    if (button) button.disabled = false;
  }
}

function bindWindowChrome(): void {
  renderResizeControl();
  chrome.resize?.addEventListener("click", toggleWindowSize);
  chrome.hide?.addEventListener("click", minimizeToPill);
  chrome.shutdown?.addEventListener("click", () => {
    // Ending the session for good still closes the shift honestly first.
    releaseRun("client_closed");
    void invoke("shutdown").catch(() => undefined);
  });
  chrome.pill?.addEventListener("click", restoreFloor);
  // The titlebar is `data-tauri-drag-region`, which the native frame honours on
  // its own; the pill is a button, so its drag has to be asked for explicitly.
  chrome.pill?.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    void windowHandle.startDragging().catch(() => undefined);
  });

  document.querySelector("#return-code")?.addEventListener("click", minimizeToPill);
  document.querySelector("#continue-game")?.addEventListener("click", resumeRun);
  document.querySelector("#how-to-play-from-pause")?.addEventListener("click", openHowToPlay);
  document.querySelector("#return-menu")?.addEventListener("click", () => returnToMenu());
  document.querySelector("#how-to-play-close")?.addEventListener("click", closeHowToPlay);
  document.querySelector("#signout-confirm")?.addEventListener("click", () => void confirmSignOut());
  document.querySelector("#signout-cancel")?.addEventListener("click", closeSignOutPrompt);
}

function drawGate(): void {
  screen = "gate";

