  holdRun("player");
  mode = "pill";
  document.body.dataset.mode = "pill";
  void applyWindowSize();
  chrome.pill?.focus();
}

function restoreFloor(): void {
  if (mode !== "pill") return;
  mode = "floor";
  delete document.body.dataset.mode;
  // README: the pill restores to the compact floor, whatever it collapsed from.
  expanded = false;
  renderResizeControl();
  // The pill can be dragged anywhere, and a full frame pinned to the corner it
  // was dropped in would open mostly off-screen.
  void applyWindowSize().then(() => windowHandle.center()).catch(() => undefined);
  // An agent pause that landed while the pill was down keeps its dialog (the
  // pill hides dialogs in CSS, it does not answer them); a hold the pill took
  // on its own is released by reopening.
  if (pauseHold && !pauseHold.prompt) resumeRun();
  else refreshPausePrompt();
}

// ── Dialogs ──────────────────────────────────────────────────────────

function dialogOpen(dialog: HTMLElement | null): boolean {
  return Boolean(dialog && !dialog.hidden);
}

/** The pause dialog is a view of the hold, never state of its own. */
function refreshPausePrompt(): void {
  const prompt = chrome.pausePrompt;
  if (!prompt) return;
  const show = pauseHold?.prompt ?? false;
  prompt.hidden = !show;
  if (show && mode !== "pill") document.querySelector<HTMLButtonElement>("#return-code")?.focus();
}

/**
 * The guide is reachable from the menu, the level list, the pause dialog and
 * the arena's own `?` hotspot. Opening it from the pause dialog stacks: the
 * shift is still held, so closing the guide puts the pause dialog back.
 */
function openHowToPlay(): void {
  if (chrome.pausePrompt) chrome.pausePrompt.hidden = true;
  if (!chrome.howToPlay) return;
  chrome.howToPlay.hidden = false;
  document.querySelector<HTMLButtonElement>("#how-to-play-close")?.focus();
}

function closeHowToPlay(): void {
  if (chrome.howToPlay) chrome.howToPlay.hidden = true;
  refreshPausePrompt();
}

function openSignOutPrompt(): void {
  if (!chrome.signOutPrompt) return;
  chrome.signOutPrompt.hidden = false;
  document.querySelector<HTMLButtonElement>("#signout-confirm")?.focus();
}

function closeSignOutPrompt(): void {
  if (chrome.signOutPrompt) chrome.signOutPrompt.hidden = true;
}

/**
 * Signing out ends the shift on the way to the gate: an abandoned run, never
 * a score. The save is left alone — it is stamped with the owner it belongs
 * to, so it stays invisible until that account signs back in.
 */
async function confirmSignOut(): Promise<void> {
  const button = document.querySelector<HTMLButtonElement>("#signout-confirm");
  if (button) button.disabled = true;
  try {
    releaseRun("user_quit");
    await signOut();
    closeSignOutPrompt();
    savedGame = undefined;
    cursor = -1;
    drawGate();
  } catch (err) {
    console.error("Failed to sign out:", err);
    setSyncError("Could not sign out. Try again.");
  } finally {
    if (button) button.disabled = false;
  }
}

