// ── Session lifecycle ────────────────────────────────────────────────
//
// One run at a time, and exactly one owner for each of its four exits:
// finishing (`finishRun`), leaving for the menu (`returnToMenu`), starting
// over (`restartRun`) and being torn down for something else entirely
// (`releaseRun` — sign-out, shutdown, a host reset). Only the first of those
// ever writes a score.

function currentVariationId(): string {
  return entry?.variations[variationCursor]?.id ?? entry?.variations[0]?.id ?? "classic";
}

/**
 * A fresh seed for a fresh run. `previous` is re-rolled away from, so
 * "restart" can never quietly mean "play the same night again".
 */
function newSeed(previous?: number): number {
  const buffer = new Uint32Array(1);
  let seed = previous ?? 0;
  do {
    crypto.getRandomValues(buffer);
    seed = buffer[0]!;
  } while (seed === previous);
  return seed;
}

function clearTickTimer(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

/**
 * Re-enter whichever scheduler this run is paced by.
 *
 * A live crew owns its own clock: the orchestrator runs a full staff round and
 * steps the engine itself, so all this does is make sure it is pumping. With a
 * deterministic crew there is nobody to do that, and the shell drives `tick`
 * on the cadence the engine asks for — `tickMs()` returns 0 whenever the clock
 * should be still (service not open, paused, a decision card up, shift over),
 * so "no timer" is a state the engine is allowed to choose.
 *
 * Called from `drawGame`, which is why every path that repaints the board also
 * puts the clock back where it belongs.
 */
function syncScheduler(): void {
  clearTickTimer();
  const activeGame = game;
  if (!activeGame || screen !== "game" || gameEnded || replaying || pauseHold) return;
  if (activeGame.isOver()) return;
  if (workerOrchestrator) {
    workerOrchestrator.start();
    return;
  }
  const interval = activeGame.tickMs?.() ?? 0;
  if (interval <= 0) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (game !== activeGame || gameEnded || pauseHold || activeGame.isOver()) return;
    stepGame("tick", "environment");
    actionsTaken++;
    drawGame();
    if (activeGame.isOver()) finishRun();
  }, interval);
}

function simSnapshot(): SimSnapshot | undefined {
  if (!game || game.name !== "restaurant-arena") return undefined;
  const view = arenaView(game);
  return {
    started: Boolean(view.sim?.started),
    running: Boolean(view.sim?.running),
    decisionOpen: Boolean(view.decision),
  };
}

/**
 * Stop the shift. `agent` is the `Stop` hook asking for the player back and
 * raises the dialog; `player` is the pill going down and raises nothing. The
 * engine's pause is a *toggle*, so `planPause` allows exactly one per hold.
 */
function holdRun(source: PauseSource): void {
  const plan = planPause({
    source,
    autoPause: settings.autoPauseOnStop,
    inGame: screen === "game" && Boolean(game),
    over: Boolean(game?.isOver()),
    sim: simSnapshot(),
    hold: pauseHold,
  });
  pauseHold = plan.hold;
  clearTickTimer();
  workerOrchestrator?.pause();
  if (plan.stopClock) {
    stepGame("sim_toggle", "human");
    drawGame();
  }
  refreshPausePrompt();
}

/** Lift the hold and hand the clock back to whatever was driving it. */
function resumeRun(): void {
  const plan = planResume(pauseHold);
  pauseHold = null;
  refreshPausePrompt();
  if (plan.startClock && game && !game.isOver() && !gameEnded) stepGame("sim_toggle", "human");
  if (screen === "game" && game) drawGame();
  else syncScheduler();
}

function saveRun(): void {
  if (!entry || !game || gameEnded || replaying) return;
  saveGame({
    ownerId: signedInUser()?.id ?? "",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: currentVariationId(),
    seed: runSeed,
    actions: runActions,
  });
}

/**
 * Journal one applied action: the recording trace when recording is on, and
 * the save slot always. The save is rewritten on every action rather than at
 * the exits, so a crash, a shutdown or a closed lid costs at most one step.
 */
function recordAction(action: string, actor: TraceActor): void {
  if (replaying) return;
  runActions.push(action);
  if (activeTrace) {
    appendOverlayAction(activeTrace, action, actor);
    persistTrace(activeTrace);
    scheduleTraceFlush(activeTrace);
  }
  saveRun();
}

/** Start a run: fresh seed and journal, or a restored one replayed into place. */
function launchRun(
  selected: GameEntry,
  variationIndex: number,
  restored?: { game: PlayableGame; seed: number; actions: string[] },
): void {
  if (!selected.create || !isPlayable(selected)) return;
  releaseRun("user_quit");
  const variationId = selected.variations[variationIndex]?.id ?? selected.variations[0]?.id ?? "classic";
  entry = selected;
  cursor = Math.max(0, MENU_GAMES.indexOf(selected));
  variationCursor = Math.max(0, variationIndex);
  runSeed = restored?.seed ?? newSeed();
  runActions = [...(restored?.actions ?? [])];
  game = restored?.game ?? selected.create(variationId);
  if (!restored) game.reset(runSeed);
  gameStartedAt = Date.now();
  actionsTaken = runActions.length;
  gameEnded = false;
  replaying = false;
  pauseHold = null;
  activeTrace = createOverlayTrace(selected, variationId, runSeed);
  // A resumed run is a new episode of the same night: the journal it was
  // rebuilt from goes into the new trace so the record matches the board.
  for (const action of runActions) appendOverlayAction(activeTrace, action, actorFor(action));
  persistTrace(activeTrace);
  gameSessionId = activeTrace.gameId;
  sessionReceiptId = activeTrace.gameId;
  screen = "game";
  refreshPausePrompt();
  renderGameScreen();
  attachWorkerOrchestrator(game);
  saveRun();
  captureOverlayEvent("game.started", {
    game_type: selected.id,
    variation_id: variationId,
    resumed: Boolean(restored),
    platform: "overlay",
  }, gameSessionId);
  syncScheduler();
}

/** The environment moves the clock; everything else is the person playing. */
function actorFor(action: string): TraceActor {
  return action === "tick" || action === "bot_move" ? "environment" : "human";
}

/**
 * Tear the current run down without deciding what replaces it. Never writes a
 * score: an abandoned shift is not a result. The save is left untouched — the
 * two callers that mean to throw it away say so themselves.
 */
function releaseRun(reason: EpisodeEndReason): void {
  clearTickTimer();
  stopWorkerOrchestrator();
  pauseHold = null;
  refreshPausePrompt();
  if (game && entry && !gameEnded) {
    captureOverlayEvent("game.ended", {
      game_type: entry.id,
      variation_id: currentVariationId(),
      outcome: "abandoned",
      end_reason: reason,
      score: game.score(),
      success: false,
      duration_ms: Math.max(0, Date.now() - gameStartedAt),
      actions_taken: actionsTaken,
      platform: "overlay",
    }, gameSessionId);
    if (activeTrace) submitTrace(activeTrace, reason);
  }
  cancelTraceFlush();
  activeTrace = undefined;
  gameSessionId = undefined;
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  screenElement.querySelector(".game-end-overlay")?.remove();
  delete screenElement.dataset.game;
  game = undefined;
  gameEnded = false;
  replaying = false;
  runActions = [];
  actionsTaken = 0;
}

/**
 * End the shift and go back to the menu. The save is deliberately left where
 * it is: this is the exit that lets the identical run be resumed later.
 */
function returnToMenu(reason: EpisodeEndReason = "user_quit"): void {
  releaseRun(reason);
  refreshSavedGame();
  screen = "menu";
  cursor = -1;
  drawMenu();
}

/**
 * Start over on the same game and variation. The old run's save is thrown
 * away and the new one gets a freshly randomized seed — restart means "a new
 * run", not "the same night again".
 */
function restartRun(): void {
  if (!entry) return;
  const selected = entry;
  const variationIndex = variationCursor;
  const previousSeed = runSeed;
  releaseRun("restart");
  clearSavedGame();
  savedGame = undefined;
  launchRun(selected, variationIndex);
  // `launchRun` rolls its own seed; only the "never the seed it replaces"
  // promise needs the old value.
  if (runSeed === previousSeed && game) {
    runSeed = newSeed(previousSeed);
    game.reset(runSeed);
    runActions = [];
    saveRun();
    drawGame();
  }
}

/** Rebuild the run in the save slot, if this account still has one to resume. */
function resumeSavedGame(): void {
  const saved = savedGame;
  if (!saved) return;
  const selected = MENU_GAMES.find(({ id }) => id === saved.gameId);
  const restored = selected && isPlayable(selected) ? restoreGame(selected, saved) : null;
  // A save from an older build of the game, or of a shift that already ended,
  // cannot be resumed. Drop it rather than leave a button that does nothing.
  if (!selected || !restored || restored.game.isOver()) {
    clearSavedGame();
    savedGame = undefined;
    if (screen === "menu") drawMenu();
    return;
  }
  const variationIndex = selected.variations.findIndex(({ id }) => id === saved.variationId);
  launchRun(selected, Math.max(0, variationIndex), {
    game: restored.game,
    seed: saved.seed,
    actions: restored.actions,
  });
}

function refreshSavedGame(): void {
  const saved = loadSavedGame();
  savedGame = saved && saved.ownerId === (signedInUser()?.id ?? "") ? saved : undefined;
}

function durationLabel(ms: number): string {
  const total = Math.max(0, Math.round(ms / 1000));
  return `${Math.floor(total / 60)}m ${String(total % 60).padStart(2, "0")}s`;
}

/**
 * The shift ended on its own terms, which is the only exit that produces a
 * result: a local score row (idempotent on the run's id, so a repaint cannot
 * double it) and a completed trace.
 */
function finishRun(): void {
  if (!game || !entry || gameEnded || replaying) return;
  const activeGame = game;
  const selected = entry;
  gameEnded = true;
  clearTickTimer();
  stopWorkerOrchestrator();
  pauseHold = null;
  refreshPausePrompt();
  const won = activeGame.hasWon();
  const score = activeGame.score();
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const variationId = currentVariationId();
  captureOverlayEvent("game.ended", {
    game_type: selected.id,
    variation_id: variationId,
    outcome: "completed",
    end_reason: won ? "won" : "lost",
    score,
    success: won,
    duration_ms: durationMs,
    actions_taken: actionsTaken,
    platform: "overlay",
  }, gameSessionId);
  void invoke("append_local_score", {
    score: {
      game_id: sessionReceiptId ?? `game_${runSeed}`,
      game_type: selected.id,
      variation_id: variationId,
      score,
      success: won,
      completed_at: new Date().toISOString(),
      duration_ms: durationMs,
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
  if (activeTrace) {
    submitTrace(activeTrace, won ? "won" : "lost", score);
    activeTrace = undefined;
  }
  cancelTraceFlush();
  lastReplay = { entry: selected, variationId, seed: runSeed, actions: [...runActions] };
  // Nothing left to resume: the run in the save slot is this finished one.
  clearSavedGame();
  savedGame = undefined;
  renderGameEnd();
}

