  actionsTaken = 0;
}

/**
 * End the shift and go back to the menu. The save is deliberately left where
 * it is: this is the exit that lets the identical run be resumed later.
 */
function returnToMenu(reason: EpisodeEndReason = "user_quit"): void {
  releaseRun(reason);
  refreshSavedGame();
  screen = "menu";
  cursor = -1;
  drawMenu();
}

/**
 * Start over on the same game and variation. The old run's save is thrown
 * away and the new one gets a freshly randomized seed — restart means "a new
 * run", not "the same night again".
 */
function restartRun(): void {
  if (!entry) return;
  const selected = entry;
  const variationIndex = variationCursor;
  const previousSeed = runSeed;
  releaseRun("restart");
  clearSavedGame();
  savedGame = undefined;
  launchRun(selected, variationIndex);
  // `launchRun` rolls its own seed; only the "never the seed it replaces"
  // promise needs the old value.
  if (runSeed === previousSeed && game) {
    runSeed = newSeed(previousSeed);
    game.reset(runSeed);
    runActions = [];
    saveRun();
    drawGame();
  }
}

/** Rebuild the run in the save slot, if this account still has one to resume. */
function resumeSavedGame(): void {
  const saved = savedGame;
  if (!saved) return;
  const selected = MENU_GAMES.find(({ id }) => id === saved.gameId);
  const restored = selected && isPlayable(selected) ? restoreGame(selected, saved) : null;
  // A save from an older build of the game, or of a shift that already ended,
  // cannot be resumed. Drop it rather than leave a button that does nothing.
  if (!selected || !restored || restored.game.isOver()) {
    clearSavedGame();
    savedGame = undefined;
    if (screen === "menu") drawMenu();
    return;
  }
  const variationIndex = selected.variations.findIndex(({ id }) => id === saved.variationId);
  launchRun(selected, Math.max(0, variationIndex), {
    game: restored.game,
    seed: saved.seed,
    actions: restored.actions,
  });
}

function refreshSavedGame(): void {
  const saved = loadSavedGame();
  savedGame = saved && saved.ownerId === (signedInUser()?.id ?? "") ? saved : undefined;
}

function durationLabel(ms: number): string {
  const total = Math.max(0, Math.round(ms / 1000));
  return `${Math.floor(total / 60)}m ${String(total % 60).padStart(2, "0")}s`;
}

/**
 * The shift ended on its own terms, which is the only exit that produces a
 * result: a local score row (idempotent on the run's id, so a repaint cannot
 * double it) and a completed trace.
 */
function finishRun(): void {
  if (!game || !entry || gameEnded || replaying) return;
  const activeGame = game;
  const selected = entry;
  gameEnded = true;
  clearTickTimer();
  stopWorkerOrchestrator();
  pauseHold = null;
  refreshPausePrompt();
  const won = activeGame.hasWon();
  const score = activeGame.score();
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const variationId = currentVariationId();
  captureOverlayEvent("game.ended", {
    game_type: selected.id,
    variation_id: variationId,
    outcome: "completed",
    end_reason: won ? "won" : "lost",
    score,
    success: won,
    duration_ms: durationMs,
    actions_taken: actionsTaken,
    platform: "overlay",
  }, gameSessionId);
  void invoke("append_local_score", {
    score: {
      game_id: sessionReceiptId ?? `game_${runSeed}`,
      game_type: selected.id,
      variation_id: variationId,
      score,
      success: won,
      completed_at: new Date().toISOString(),
      duration_ms: durationMs,
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
  if (activeTrace) {
    submitTrace(activeTrace, won ? "won" : "lost", score);
    activeTrace = undefined;
  }
  cancelTraceFlush();
  lastReplay = { entry: selected, variationId, seed: runSeed, actions: [...runActions] };
  // Nothing left to resume: the run in the save slot is this finished one.
  clearSavedGame();
  savedGame = undefined;
  renderGameEnd();
}

/**
 * The end-of-shift card, over the board it belongs to. Built from the run's
 * own journal (debrief, evidence, timeline, session id) and offering the four
 * things there are to do next: another run, the menu, the trace, or back to
 * the terminal.
 */
function renderGameEnd(): void {
  if (!game || !entry || !gameEnded) return;
  const board = screenElement.querySelector<HTMLElement>(".board");
  if (!board) return;
  board.querySelector(".game-end-overlay")?.remove();
  const won = game.hasWon();
  const score = game.score();
  const best = personalBest(entry.id, score);
  const isArena = game.name === "restaurant-arena";
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = won ? "win" : "loss";
  overlay.innerHTML = `<div class="game-end-content${isArena ? " arena-end-content" : ""}">
    <h2 class="game-end-title">${won ? "Shift complete" : "Shift over"}</h2>
    <p class="game-end-stats">Score <strong>${score}</strong>${best === undefined ? "" : ` · Personal best ${best}`}<br />${actionsTaken} action${actionsTaken === 1 ? "" : "s"} · ${durationLabel(Date.now() - gameStartedAt)}</p>
    ${getArenaDebriefHtml()}
    ${getArenaEvidenceHtml()}
    ${sessionReceiptHtml()}
    ${getArenaTimelineHtml()}
    <div class="game-end-actions">
      <button type="button" class="primary" data-end-action="restart"><kbd>R</kbd> New run</button>
      ${isArena ? `<div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">📥 Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
      </div>` : ""}
      <button type="button" data-end-action="menu"><kbd>M</kbd> Menu</button>
      <button type="button" data-end-action="coding"><kbd>Esc</kbd> Coding</button>
    </div>
  </div>`;
  board.appendChild(overlay);
  overlay.querySelector<HTMLButtonElement>('[data-end-action="restart"]')?.focus();
}

