/**
 * Honour a `--show <game>` launch. It can arrive before the arcade has loaded
 * its settings or its session, so it is parked until there is a menu to leave.
 */
function requestLaunch(gameId: string, variationId: string): void {
  if (screen === "gate" || !entry && !isPlayable(MENU_GAMES.find(({ id }) => id === gameId) ?? MENU_GAMES[0]!)) {
    pendingLaunch = { game: gameId, variation: variationId };
    return;
  }
  pendingLaunch = { game: gameId, variation: variationId };
  applyPendingLaunch();
}

function applyPendingLaunch(): void {
  const request = pendingLaunch;
  if (!request || screen === "gate") return;
  pendingLaunch = undefined;
  const selected = MENU_GAMES.find(({ id }) => id === request.game);
  if (!selected || !isPlayable(selected)) return;
  // A run of the requested game is already on screen; the host asking again
  // (a second prompt in the same session) must not restart it.
  if (screen === "game" && entry?.id === selected.id && !gameEnded) return;
  const index = selected.variations.findIndex(({ id }) => id === request.variation);
  if (request.variation && index === -1) {
    // Named a variation this build does not have: show the level list instead
    // of silently playing a different one.
    entry = selected;
    cursor = Math.max(0, MENU_GAMES.indexOf(selected));
    variationCursor = 0;
    screen = "variations";
    drawVariations();
    return;
  }
  launchRun(selected, Math.max(0, index));
}

