chrome.pill?.addEventListener("click", restoreFloor);
// The titlebar is `data-tauri-drag-region`, which the native frame honours on
// its own; the pill is a button, so its drag has to be asked for explicitly.
// Only once the pointer has actually travelled, though: handing the window
// over on `pointerdown` would eat the click that reopens the floor.
chrome.pill?.addEventListener("pointerdown", (event) => {
  if (event.button !== 0) return;
  const origin = { x: event.clientX, y: event.clientY };
  const onMove = (move: PointerEvent) => {
    if (Math.abs(move.clientX - origin.x) < 4 && Math.abs(move.clientY - origin.y) < 4) return;
    stop();
    void windowHandle.startDragging().catch(() => undefined);
  };
  const stop = () => {
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", stop);
  };
  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", stop);
});

