import { describe, expect, test } from "bun:test";
import { REGISTRY, isPlayable } from "../src/games/registry.js";
import { clearSavedGame, loadSavedGame, restoreGame, saveGame, type SavedGame } from "./persistence.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";

function memoryStorage(): Storage {
  const map = new Map<string, string>();
  return {
    get length() {
      return map.size;
    },
    clear: () => map.clear(),
    getItem: (key: string) => map.get(key) ?? null,
    key: (index: number) => [...map.keys()][index] ?? null,
    removeItem: (key: string) => void map.delete(key),
    setItem: (key: string, value: string) => void map.set(key, value),
  } as Storage;
}

const arena = REGISTRY.find((entry) => entry.id === "restaurant-arena")!;
const variationId = arena.variations[1]!.id;

/** A short shift: open the doors, run the clock, hold the door once. */
const PLAYED = ["sim_toggle", "tick", "tick", "hold_seating", "tick"];

function savedRun(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_1",
    gameId: arena.id,
    gameVersion: arena.version,
    variationId,
    seed: 7,
    actions: [...PLAYED],
    ...overrides,
  };
}

describe("session save slot", () => {
  test("round-trips the run currently on screen", () => {
    const storage = memoryStorage();
    const { schemaVersion, ...run } = savedRun();
    saveGame(run, storage);
    // The version stamp is the loader's contract, so the writer owns it.
    expect(schemaVersion).toBe(1);
    expect(loadSavedGame(storage)).toEqual(savedRun());
  });

  test("keeps exactly one record, whatever it is asked to save", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    saveGame(savedRun({ seed: 99, actions: ["sim_toggle"] }), storage);
    expect(storage.length).toBe(1);
    expect(loadSavedGame(storage)?.seed).toBe(99);
  });

  test("clearing leaves nothing to resume", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    clearSavedGame(storage);
    expect(storage.getItem(STORAGE_KEY)).toBeNull();
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("drops a journal too long to load instead of writing an unloadable one", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    saveGame(savedRun({ actions: Array.from({ length: 50_001 }, () => "tick") }), storage);
    // Writing it would produce a record `loadSavedGame` refuses, which reads to
    // the player as a Resume button that silently rewinds their shift.
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("refuses a record from another schema, and malformed JSON", () => {
    const storage = memoryStorage();
    storage.setItem(STORAGE_KEY, JSON.stringify({ ...savedRun(), schemaVersion: 2 }));
    expect(loadSavedGame(storage)).toBeNull();
    storage.setItem(STORAGE_KEY, "{not json");
    expect(loadSavedGame(storage)).toBeNull();
  });
});

describe("rebuilding a saved run", () => {
  test("replays the seed and journal back to the same board", () => {
    expect(isPlayable(arena)).toBe(true);
    const played = arena.create!(variationId);
    played.reset(7);
    for (const action of PLAYED) played.step(action);

    const restored = restoreGame(arena, savedRun());
    expect(restored?.actions).toEqual(PLAYED);
    // Same seed, same actions, same night — the engine is deterministic, which
    // is the whole reason a run can be stored as a seed plus a list of moves.
    expect(JSON.stringify(restored?.game.state())).toBe(JSON.stringify(played.state()));
    expect(restored?.game.score()).toBe(played.score());
  });

  test("refuses a save written by another version of the game", () => {
    expect(restoreGame(arena, savedRun({ gameVersion: "0" }))).toBeNull();
    expect(restoreGame(arena, savedRun({ gameId: "not-a-game" }))).toBeNull();
  });

  test("refuses a journal holding an action this build no longer accepts", () => {
    // Rebuilding around the missing move would produce a different shift than
    // the one that was saved, which is worse than offering no resume at all.
    expect(restoreGame(arena, savedRun({ actions: ["sim_toggle", "garnish_the_plate"] }))).toBeNull();
  });
});

