import { describe, expect, test } from "bun:test";
import { clockRunning, planPause, planResume, type PauseHold, type PauseRequest } from "./pause-state.js";

const RUNNING = { started: true, running: true };

function request(overrides: Partial<PauseRequest> = {}): PauseRequest {
  return {
    source: "agent",
    autoPause: true,
    inGame: true,
    over: false,
    sim: RUNNING,
    hold: null,
    ...overrides,
  };
}

describe("the clock reading a hold is taken against", () => {
  test("only counts a shift that is actually ticking", () => {
    expect(clockRunning(RUNNING)).toBe(true);
    expect(clockRunning({ started: false, running: true })).toBe(false);
    expect(clockRunning({ started: true, running: false })).toBe(false);
    expect(clockRunning(undefined)).toBe(false);
  });

  test("treats an open decision as already stopped", () => {
    // The engine refuses `sim_toggle` while a decision is up and `tickMs()`
    // already returns 0, so a hold that claimed to stop the clock would toggle
    // service back on when it resumed.
    expect(clockRunning({ ...RUNNING, decisionOpen: true })).toBe(false);
  });
});

describe("the agent stopping", () => {
  test("stops the shift once and asks for the player", () => {
    const plan = planPause(request());
    expect(plan.stopClock).toBe(true);
    expect(plan.hold).toEqual({ source: "agent", resumeClock: true, prompt: true });
  });

  test("does nothing at all when auto-pause is switched off", () => {
    const plan = planPause(request({ autoPause: false }));
    expect(plan).toEqual({ hold: null, stopClock: false });
  });

  test("leaves the menu alone — there is no shift to hold", () => {
    expect(planPause(request({ inGame: false }))).toEqual({ hold: null, stopClock: false });
  });

  test("leaves a finished shift alone — the end card owns the screen", () => {
    expect(planPause(request({ over: true }))).toEqual({ hold: null, stopClock: false });
  });

  test("holds a shift that never opened without pretending to stop it", () => {
    const plan = planPause(request({ sim: { started: false, running: false } }));
    expect(plan.stopClock).toBe(false);
    expect(plan.hold).toEqual({ source: "agent", resumeClock: false, prompt: true });
  });
});

describe("the player minimizing", () => {
  test("holds the shift silently — the pill has nothing to say", () => {
    const plan = planPause(request({ source: "player" }));
    expect(plan.stopClock).toBe(true);
    expect(plan.hold).toEqual({ source: "player", resumeClock: true, prompt: false });
  });

  test("still holds when auto-pause is off", () => {
    // Auto-pause governs the agent. A shift left ticking behind a 144 × 48
    // pill burns down unattended whatever that setting says.
    const plan = planPause(request({ source: "player", autoPause: false }));
    expect(plan.stopClock).toBe(true);
    expect(plan.hold?.source).toBe("player");
  });
});

describe("a second pause on a held shift", () => {
  const held: PauseHold = { source: "player", resumeClock: true, prompt: false };

  test("never toggles the engine clock again", () => {
    // `sim_toggle` is a toggle: a doubled stop would start service back up.
    const plan = planPause(request({ hold: held, sim: { started: true, running: false } }));
    expect(plan.stopClock).toBe(false);
  });

  test("keeps the first hold's reading of what to restart", () => {
    const plan = planPause(request({ hold: held, sim: { started: true, running: false } }));
    expect(plan.hold?.resumeClock).toBe(true);
  });

  test("lets the agent raise its dialog over a hold the pill already took", () => {
    expect(planPause(request({ hold: held })).hold?.prompt).toBe(true);
  });

  test("does not raise a dialog when the player minimizes over an agent hold", () => {
    const agentHold: PauseHold = { source: "agent", resumeClock: true, prompt: true };
    // The dialog is still unanswered, so it survives the pill going down.
    expect(planPause(request({ source: "player", hold: agentHold })).hold?.prompt).toBe(true);
  });
});

describe("resuming", () => {
  test("restarts only a clock this hold stopped", () => {
    expect(planResume({ source: "agent", resumeClock: true, prompt: true })).toEqual({ hold: null, startClock: true });
    expect(planResume({ source: "agent", resumeClock: false, prompt: true })).toEqual({ hold: null, startClock: false });
  });

  test("is a no-op with nothing held", () => {
    expect(planResume(null)).toEqual({ hold: null, startClock: false });
  });
});

