import { GlobalRegistrator } from "@happy-dom/global-registrator";
import { readFileSync } from "node:fs";

GlobalRegistrator.register({ url: "http://localhost/index.html", width: 600, height: 850 });

const html = readFileSync("/app/overlay/dist/index.html", "utf8");
document.documentElement.innerHTML = html.replace(/<script[\s\S]*?<\/script>/g, "");

const resizes: Array<{ width: number; height: number }> = [];
window.addEventListener("gamepigeon:preview-resize", (event) => {
  resizes.push((event as CustomEvent).detail);
});

// The bundle is a module; import it once the DOM it queries exists.
await import("/app/overlay/dist/app.js");

const tick = () => new Promise((resolve) => setTimeout(resolve, 30));
await tick();
await tick();

const screenEl = document.querySelector("#screen")!;
const click = (selector: string) => {
  const el = document.querySelector<HTMLElement>(selector);
  if (!el) throw new Error(`missing ${selector}`);
  el.dispatchEvent(new window.MouseEvent("click", { bubbles: true }));
};
const key = (init: KeyboardEventInit) => window.dispatchEvent(new window.KeyboardEvent("keydown", { bubbles: true, ...init }));
const saved = () => JSON.parse(localStorage.getItem("gamepigeon.arcade.active-game.v1") ?? "null");
const visible = (selector: string) => !document.querySelector<HTMLElement>(selector)!.hidden;
const report: string[] = [];
const check = (label: string, ok: unknown) => report.push(`${ok ? "ok  " : "FAIL"} ${label}`);

check("boots to the menu", screenEl.getAttribute("data-screen") === "menu");
check("applies the compact frame at boot", JSON.stringify(resizes[0]) === '{"width":600,"height":850}');

click('[data-game-index="0"]');
check("game card opens the level list", screenEl.getAttribute("data-screen") === "variations");

click('[data-variation-index="1"]');
await tick();
check("variation launches a run", screenEl.getAttribute("data-screen") === "game");
check("run is saved", saved()?.gameId === "restaurant-arena" && saved()?.variationId === "dinner-rush");
const firstSeed = saved()?.seed;

// Play: space opens the doors and the clock starts.
key({ key: " " });
await tick();
check("space is journalled", JSON.stringify(saved()?.actions) === '["sim_toggle"]');

// Agent stop → pause dialog, clock held.
window.dispatchEvent(new window.Event("gamepigeon:pause"));
check("agent stop raises the pause dialog", visible("#return-prompt"));
check("agent stop pauses the shift", JSON.stringify(saved()?.actions) === '["sim_toggle","sim_toggle"]');
click("#how-to-play-from-pause");
check("guide opens over the pause dialog", visible("#how-to-play") && !visible("#return-prompt"));
click("#how-to-play-close");
check("closing the guide restores the pause dialog", !visible("#how-to-play") && visible("#return-prompt"));
click("#continue-game");
check("continue hides the dialog", !visible("#return-prompt"));
check("continue restarts the clock", saved()?.actions.length === 3);

// Window chrome.
click("#resize");
check("resize expands", JSON.stringify(resizes.at(-1)) === '{"width":830,"height":900}');
check("resize control names its next state", document.querySelector("#resize")!.textContent === "↙");
click("#resize");
check("resize compacts again", JSON.stringify(resizes.at(-1)) === '{"width":600,"height":850}');
click("#hide");
check("hide collapses to the pill", document.body.dataset.mode === "pill");
check("pill frame", JSON.stringify(resizes.at(-1)) === '{"width":144,"height":48}');
check("pill holds the shift", saved()?.actions.length === 4);
click("#pill");
await tick();
check("pill restores the floor", document.body.dataset.mode === undefined);
check("pill frame restores compact", JSON.stringify(resizes.at(-1)) === '{"width":600,"height":850}');
check("restore resumes the shift", saved()?.actions.length === 5);

// Escape also collapses, and the pill takes Enter.
key({ key: "Escape" });
check("escape collapses to the pill", document.body.dataset.mode === "pill");
key({ key: "Enter" });
await tick();
check("enter reopens", document.body.dataset.mode === undefined);

// Restart: new seed, save thrown away and rebuilt.
key({ key: "r" });
await tick();
check("restart keeps playing the same variation", screenEl.getAttribute("data-screen") === "game");
check("restart rolls a new seed", typeof saved()?.seed === "number" && saved()?.seed !== firstSeed);
check("restart empties the journal", JSON.stringify(saved()?.actions) === "[]");

// End the shift back to the menu; the save survives for a resume.
key({ key: " " });
const midSeed = saved()?.seed;
key({ key: "m" });
await tick();
check("m ends the shift back to the menu", screenEl.getAttribute("data-screen") === "menu");
check("menu keeps the save", saved()?.seed === midSeed);
check("menu offers a resume", Boolean(document.querySelector("[data-resume]")));
click("[data-resume]");
await tick();
check("resume rebuilds the run", screenEl.getAttribute("data-screen") === "game" && saved()?.seed === midSeed);
check("resume keeps the journal", JSON.stringify(saved()?.actions) === '["sim_toggle"]');

// How to Play from the menu, and the sign-out confirmation.
key({ key: "m" });
await tick();
click("[data-open-how-to-play]");
check("menu opens the guide", visible("#how-to-play"));
key({ key: "Escape" });
check("escape closes the guide without collapsing", !visible("#how-to-play") && document.body.dataset.mode === undefined);

const chip = document.querySelector<HTMLElement>("#account-chip")!;
chip.hidden = false;
click("#account-chip");
check("signed-out preview chip does not ask to sign out", !visible("#signout-prompt"));

console.log(report.join("\n"));
console.log(report.some((line) => line.startsWith("FAIL")) ? "\nSMOKE FAILED" : "\nSMOKE OK");
GlobalRegistrator.unregister();

