import { describe, expect, test } from "bun:test";
import { clockRunning, planPause, planResume, type PauseHold, type PauseRequest } from "./pause-state.js";

const RUNNING = { started: true, running: true };

function request(overrides: Partial<PauseRequest> = {}): PauseRequest {
  return {
    source: "agent",
    autoPause: true,
    inGame: true,
    over: false,
    sim: RUNNING,
    hold: null,
    ...overrides,
  };
}

describe("the clock reading a hold is taken against", () => {
  test("only counts a shift that is actually ticking", () => {
    expect(clockRunning(RUNNING)).toBe(true);
    expect(clockRunning({ started: false, running: true })).toBe(false);
    expect(clockRunning({ started: true, running: false })).toBe(false);
    expect(clockRunning(undefined)).toBe(false);
  });

  test("treats an open decision as already stopped", () => {
    // The engine refuses `sim_toggle` while a decision is up and `tickMs()`
    // already returns 0, so a hold that claimed to stop the clock would toggle
    // service back on when it resumed.
    expect(clockRunning({ ...RUNNING, decisionOpen: true })).toBe(false);
  });
});

describe("the agent stopping", () => {
  test("stops the shift once and asks for the player", () => {
    const plan = planPause(request());
    expect(plan.stopClock).toBe(true);
    expect(plan.hold).toEqual({ source: "agent", resumeClock: true, prompt: true });
  });

  test("does nothing at all when auto-pause is switched off", () => {
    const plan = planPause(request({ autoPause: false }));
    expect(plan).toEqual({ hold: null, stopClock: false });
  });

  test("leaves the menu alone — there is no shift to hold", () => {
    expect(planPause(request({ inGame: false }))).toEqual({ hold: null, stopClock: false });
  });

  test("leaves a finished shift alone — the end card owns the screen", () => {
    expect(planPause(request({ over: true }))).toEqual({ hold: null, stopClock: false });
  });

  test("holds a shift that never opened without pretending to stop it", () => {
    const plan = planPause(request({ sim: { started: false, running: false } }));
    expect(plan.stopClock).toBe(false);
    expect(plan.hold).toEqual({ source: "agent", resumeClock: false, prompt: true });
  });
});

describe("the player minimizing", () => {
  test("holds the shift silently — the pill has nothing to say", () => {
    const plan = planPause(request({ source: "player" }));
    expect(plan.stopClock).toBe(true);
    expect(plan.hold).toEqual({ source: "player", resumeClock: true, prompt: false });
  });

  test("still holds when auto-pause is off", () => {
    // Auto-pause governs the agent. A shift left ticking behind a 144 × 48
    // pill burns down unattended whatever that setting says.
    const plan = planPause(request({ source: "player", autoPause: false }));
    expect(plan.stopClock).toBe(true);
    expect(plan.hold?.source).toBe("player");
  });
});

describe("a second pause on a held shift", () => {
  const held: PauseHold = { source: "player", resumeClock: true, prompt: false };

  test("never toggles the engine clock again", () => {
    // `sim_toggle` is a toggle: a doubled stop would start service back up.
    const plan = planPause(request({ hold: held, sim: { started: true, running: false } }));
    expect(plan.stopClock).toBe(false);
  });

  test("keeps the first hold's reading of what to restart", () => {
    const plan = planPause(request({ hold: held, sim: { started: true, running: false } }));
    expect(plan.hold?.resumeClock).toBe(true);
  });

  test("lets the agent raise its dialog over a hold the pill already took", () => {
    expect(planPause(request({ hold: held })).hold?.prompt).toBe(true);
  });

  test("does not raise a dialog when the player minimizes over an agent hold", () => {
    const agentHold: PauseHold = { source: "agent", resumeClock: true, prompt: true };
    // The dialog is still unanswered, so it survives the pill going down.
    expect(planPause(request({ source: "player", hold: agentHold })).hold?.prompt).toBe(true);
  });
});

describe("resuming", () => {
  test("restarts only a clock this hold stopped", () => {
    expect(planResume({ source: "agent", resumeClock: true, prompt: true })).toEqual({ hold: null, startClock: true });
    expect(planResume({ source: "agent", resumeClock: false, prompt: true })).toEqual({ hold: null, startClock: false });
  });

  test("is a no-op with nothing held", () => {
    expect(planResume(null)).toEqual({ hold: null, startClock: false });
  });
});

import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  LogicalSize,
  MIN_SIZE,
  PILL_SIZE,
  isTauri,
  overlayLogicalSize,
} from "./tauri-bridge.js";

describe("overlay frame sizes", () => {
  test("are the exact sizes the README documents", () => {
    // The browser preview frames itself at these numbers independently
    // (overlay/preview.html), so a drift here silently splits the preview from
    // the native window it is supposed to mirror pixel for pixel.
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("expanding only ever grows the frame", () => {
    expect(EXPANDED_SIZE.width).toBeGreaterThan(COMPACT_SIZE.width);
    expect(EXPANDED_SIZE.height).toBeGreaterThan(COMPACT_SIZE.height);
  });

  test("both floor sizes clear the floor minimum", () => {
    for (const size of [COMPACT_SIZE, EXPANDED_SIZE]) {
      expect(size.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
      expect(size.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
    }
  });

  test("the pill does not fit inside the floor minimum", () => {
    // Which is why minimizing has to lower the minimum before it resizes, and
    // restoring has to raise it again.
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
  });
});

describe("preview fallbacks", () => {
  test("reports no Tauri host without the injected globals", () => {
    expect(isTauri()).toBe(false);
  });

  test("hands back a plain logical size the preview can measure", () => {
    const size = overlayLogicalSize(PILL_SIZE.width, PILL_SIZE.height);
    expect(size).toBeInstanceOf(LogicalSize);
    expect(size.width).toBe(144);
    expect(size.height).toBe(48);
  });
});

import { describe, expect, test } from "bun:test";
import { REGISTRY, isPlayable } from "../src/games/registry.js";
import { clearSavedGame, loadSavedGame, restoreGame, saveGame, type SavedGame } from "./persistence.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";

function memoryStorage(): Storage {
  const map = new Map<string, string>();
  return {
    get length() {
      return map.size;
    },
    clear: () => map.clear(),
    getItem: (key: string) => map.get(key) ?? null,
    key: (index: number) => [...map.keys()][index] ?? null,
    removeItem: (key: string) => void map.delete(key),
    setItem: (key: string, value: string) => void map.set(key, value),
  } as Storage;
}

const arena = REGISTRY.find((entry) => entry.id === "restaurant-arena")!;
const variationId = arena.variations[1]!.id;

/** A short shift: open the doors, run the clock, hold the door once. */
const PLAYED = ["sim_toggle", "tick", "tick", "hold_seating", "tick"];

function savedRun(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_1",
    gameId: arena.id,
    gameVersion: arena.version,
    variationId,
    seed: 7,
    actions: [...PLAYED],
    ...overrides,
  };
}

describe("session save slot", () => {
  test("round-trips the run currently on screen", () => {
    const storage = memoryStorage();
    const { schemaVersion, ...run } = savedRun();
    saveGame(run, storage);
    // The version stamp is the loader's contract, so the writer owns it.
    expect(schemaVersion).toBe(1);
    expect(loadSavedGame(storage)).toEqual(savedRun());
  });

  test("keeps exactly one record, whatever it is asked to save", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    saveGame(savedRun({ seed: 99, actions: ["sim_toggle"] }), storage);
    expect(storage.length).toBe(1);
    expect(loadSavedGame(storage)?.seed).toBe(99);
  });

  test("clearing leaves nothing to resume", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    clearSavedGame(storage);
    expect(storage.getItem(STORAGE_KEY)).toBeNull();
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("drops a journal too long to load instead of writing an unloadable one", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    saveGame(savedRun({ actions: Array.from({ length: 50_001 }, () => "tick") }), storage);
    // Writing it would produce a record `loadSavedGame` refuses, which reads to
    // the player as a Resume button that silently rewinds their shift.
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("refuses a record from another schema, and malformed JSON", () => {
    const storage = memoryStorage();
    storage.setItem(STORAGE_KEY, JSON.stringify({ ...savedRun(), schemaVersion: 2 }));
    expect(loadSavedGame(storage)).toBeNull();
    storage.setItem(STORAGE_KEY, "{not json");
    expect(loadSavedGame(storage)).toBeNull();
  });
});

describe("rebuilding a saved run", () => {
  test("replays the seed and journal back to the same board", () => {
    expect(isPlayable(arena)).toBe(true);
    const played = arena.create!(variationId);
    played.reset(7);
    for (const action of PLAYED) played.step(action);

    const restored = restoreGame(arena, savedRun());
    expect(restored?.actions).toEqual(PLAYED);
    // Same seed, same actions, same night — the engine is deterministic, which
    // is the whole reason a run can be stored as a seed plus a list of moves.
    expect(JSON.stringify(restored?.game.state())).toBe(JSON.stringify(played.state()));
    expect(restored?.game.score()).toBe(played.score());
  });

  test("refuses a save written by another version of the game", () => {
    expect(restoreGame(arena, savedRun({ gameVersion: "0" }))).toBeNull();
    expect(restoreGame(arena, savedRun({ gameId: "not-a-game" }))).toBeNull();
  });

  test("refuses a journal holding an action this build no longer accepts", () => {
    // Rebuilding around the missing move would produce a different shift than
    // the one that was saved, which is worse than offering no resume at all.
    expect(restoreGame(arena, savedRun({ actions: ["sim_toggle", "garnish_the_plate"] }))).toBeNull();
  });
});

