import { beforeAll, expect, mock, test } from "bun:test";
import { GlobalWindow } from "happy-dom";
import { readFileSync } from "node:fs";

const win = new GlobalWindow({ url: "http://localhost/index.html", width: 600, height: 850 });
{
  const names = new Set<string | symbol>();
  let node: object | null = win;
  while (node && node !== Object.prototype) {
    for (const name of Reflect.ownKeys(node)) names.add(name);
    node = Object.getPrototypeOf(node);
  }
  for (const name of names) {
    if (typeof name !== "string" || name in globalThis) continue;
    try {
      (globalThis as Record<string, unknown>)[name] = (win as unknown as Record<string, unknown>)[name];
    } catch {
      /* getters that need a live browser frame are not needed here */
    }
  }
  (globalThis as Record<string, unknown>).window = win;
  (globalThis as Record<string, unknown>).document = win.document;
  (globalThis as Record<string, unknown>).localStorage = win.localStorage;
  (globalThis as Record<string, unknown>).requestAnimationFrame = win.requestAnimationFrame.bind(win);
