import { beforeAll, expect, mock, test } from "bun:test";
import { GlobalWindow } from "happy-dom";
import { readFileSync } from "node:fs";

const win = new GlobalWindow({ url: "http://localhost/index.html", width: 600, height: 850 });
{
  const names = new Set<string | symbol>();
  let node: object | null = win;
  while (node && node !== Object.prototype) {
    for (const name of Reflect.ownKeys(node)) names.add(name);
    node = Object.getPrototypeOf(node);
  }
  for (const name of names) {
    if (typeof name !== "string" || name in globalThis) continue;
    try {
      (globalThis as Record<string, unknown>)[name] = (win as unknown as Record<string, unknown>)[name];
    } catch {
      /* getters that need a live browser frame are not needed here */
    }
  }
  // Bun ships its own Event/CustomEvent, and happy-dom's dispatchEvent rejects
  // anything that is not one of its own — the copy above skips them because the
  // names are already taken, so override them explicitly.
  for (const name of [
    "Event",
    "CustomEvent",
    "KeyboardEvent",
    "MouseEvent",
    "PointerEvent",
    "FocusEvent",
    "Node",
    "Element",
    "HTMLElement",
  ]) {
    (globalThis as Record<string, unknown>)[name] = (win as unknown as Record<string, unknown>)[name];
  }
  (globalThis as Record<string, unknown>).window = win;
  (globalThis as Record<string, unknown>).document = win.document;
  (globalThis as Record<string, unknown>).localStorage = win.localStorage;
  (globalThis as Record<string, unknown>).requestAnimationFrame = win.requestAnimationFrame.bind(win);
}
const html = readFileSync("/app/overlay/dist/index.html", "utf8");
document.documentElement.innerHTML = html.replace(/<script[\s\S]*?<\/script>/g, "");

/** Phaser cannot boot without a real canvas, and none of this needs it. */
let arenaUi: ((action: "menu" | "restart" | "help") => void) | undefined;
let arenaAction: ((action: string) => void) | undefined;
let mounts = 0;
await mock.module("/app/overlay/restaurant-arena-scene.ts", () => ({
  mountRestaurantArenaScene: (
    _parent: HTMLElement,
    _state: unknown,
    onAction: (action: string) => void,
    onUi: (action: "menu" | "restart" | "help") => void,
  ) => {
    mounts += 1;
    arenaAction = onAction;
    arenaUi = onUi;
    return { render: () => {}, setWorkerStatus: () => {}, destroy: () => {} };
  },
}));

const resizes: Array<{ width: number; height: number }> = [];
window.addEventListener("gamepigeon:preview-resize", (event) => {
  resizes.push((event as CustomEvent).detail);
});

beforeAll(async () => {
  await import("/app/overlay/app.ts");
  await settle();
});

const settle = () => new Promise((resolve) => setTimeout(resolve, 40));
const screenEl = () => document.querySelector("#screen")!;
const at = () => screenEl().getAttribute("data-screen");
const click = (selector: string) => {
  const el = document.querySelector<HTMLElement>(selector);
  if (!el) throw new Error(`missing ${selector}`);
  el.dispatchEvent(new window.MouseEvent("click", { bubbles: true }));
};
/** A real browser targets keydown at the focused element, never at `window`. */
const key = (init: KeyboardEventInit) =>
  (document.activeElement ?? document.body)!.dispatchEvent(
    new window.KeyboardEvent("keydown", { bubbles: true, ...init }),
  );
const saved = () => JSON.parse(localStorage.getItem("gamepigeon.arcade.active-game.v1") ?? "null");
const visible = (selector: string) => !document.querySelector<HTMLElement>(selector)!.hidden;
const lastSize = () => {
  const last = resizes.at(-1);
  return last ? JSON.stringify({ width: last.width, height: last.height }) : "none";
};

test("boots to the menu at the compact frame", () => {
  expect(at()).toBe("menu");
  expect(JSON.stringify({ width: resizes[0]!.width, height: resizes[0]!.height })).toBe('{"width":600,"height":850}');
});

test("a game card opens the level list and a level launches a run", async () => {
  click('[data-game-index="0"]');
  expect(at()).toBe("variations");
  click('[data-variation-index="1"]');
  await settle();
  expect(at()).toBe("game");
  expect(mounts).toBe(1);
  expect(saved()).toMatchObject({ gameId: "restaurant-arena", variationId: "dinner-rush", actions: [] });
});

test("every action is journalled into the save", () => {
  key({ key: " " });
  expect(saved().actions).toEqual(["sim_toggle"]);
});

test("an agent stop pauses the shift and offers the guide", () => {
  window.dispatchEvent(new window.Event("gamepigeon:pause"));
  expect(visible("#return-prompt")).toBe(true);
  expect(saved().actions).toEqual(["sim_toggle", "sim_toggle"]);
  click("#how-to-play-from-pause");
  expect(visible("#how-to-play")).toBe(true);
  expect(visible("#return-prompt")).toBe(false);
  click("#how-to-play-close");
  expect(visible("#return-prompt")).toBe(true);
  click("#continue-game");
  expect(visible("#return-prompt")).toBe(false);
  expect(saved().actions).toHaveLength(3);
});

test("the resize control toggles between the two documented frames", async () => {
  click("#resize");
  await settle();
  expect(lastSize()).toBe('{"width":830,"height":900}');
  expect(document.querySelector("#resize")!.textContent).toBe("↙");
  click("#resize");
  await settle();
  expect(lastSize()).toBe('{"width":600,"height":850}');
});

test("hide collapses to the pill, holding the shift, and the pill restores it", async () => {
  click("#hide");
  await settle();
  expect(document.body.dataset.mode).toBe("pill");
  expect(lastSize()).toBe('{"width":144,"height":48}');
  expect(saved().actions).toHaveLength(4);
  click("#pill");
  await settle();
  expect(document.body.dataset.mode).toBeUndefined();
  expect(lastSize()).toBe('{"width":600,"height":850}');
  expect(saved().actions).toHaveLength(5);
});

test("escape collapses and enter reopens", async () => {
  key({ key: "Escape" });
  expect(document.body.dataset.mode).toBe("pill");
  key({ key: "Enter" });
  await settle();
  expect(document.body.dataset.mode).toBeUndefined();
});

test("restart rolls a new seed and throws the old journal away", async () => {
  const before = saved().seed;
  key({ key: "r" });
  await settle();
  expect(at()).toBe("game");
  expect(saved().seed).not.toBe(before);
  expect(saved().actions).toEqual([]);
});

test("the arena's own canvas chrome restarts and reaches the guide", async () => {
  const before = saved().seed;
  arenaUi!("restart");
  await settle();
  expect(saved().seed).not.toBe(before);
  arenaUi!("help");
  expect(visible("#how-to-play")).toBe(true);
  click("#how-to-play-close");
  arenaAction!("sim_toggle");
  expect(saved().actions).toEqual(["sim_toggle"]);
});

test("ending the shift keeps the save, and the menu resumes it", async () => {
  const seed = saved().seed;
  arenaUi!("menu");
  await settle();
  expect(at()).toBe("menu");
  expect(saved().seed).toBe(seed);
  click("[data-resume]");
  await settle();
  expect(at()).toBe("game");
  expect(saved()).toMatchObject({ seed, actions: ["sim_toggle"] });
});

test("m ends the shift from the keyboard", async () => {
  key({ key: "m" });
  await settle();
  expect(at()).toBe("menu");
});

test("the menu opens the guide, and escape closes it without collapsing", () => {
  click("[data-open-how-to-play]");
  expect(visible("#how-to-play")).toBe(true);
  key({ key: "Escape" });
  expect(visible("#how-to-play")).toBe(false);
  expect(document.body.dataset.mode).toBeUndefined();
});

test("a host launch starts the named variation", async () => {
  window.dispatchEvent(new window.CustomEvent("gamepigeon:launch", { detail: { game: "restaurant-arena", variation: "quiet-tuesday" } }));
  await settle();
  expect(at()).toBe("game");
  expect(saved().variationId).toBe("quiet-tuesday");
});

test("a host reset ends the shift back to the menu but keeps the save", async () => {
  key({ key: " " });
  const seed = saved().seed;
  window.dispatchEvent(new window.Event("gamepigeon:reset"));
  await settle();
  expect(at()).toBe("menu");
  expect(saved().seed).toBe(seed);
});

test("the account chip asks before signing out, and cancelling changes nothing", async () => {
  window.dispatchEvent(new window.CustomEvent("gamepigeon:auth-success", { detail: { email: "cook@example.com" } }));
  await settle();
  click("#account-chip");
  expect(visible("#signout-prompt")).toBe(true);
  click("#signout-cancel");
  expect(visible("#signout-prompt")).toBe(false);
  expect(at()).toBe("menu");
});

test("confirming sign-out drops back to the gate", async () => {
  click("#account-chip");
  expect(visible("#signout-prompt")).toBe(true);
  click("#signout-confirm");
  await settle();
  expect(visible("#signout-prompt")).toBe(false);
  expect(at()).toBe("gate");
  expect(saved()).toBeNull();
});
